BEGIN;
ALTER TABLE public.redirect_workspace_members DROP CONSTRAINT redirect_workspace_members_pending_tenant_fence;
SET LOCAL ROLE service_role;
DO $$
DECLARE legacy uuid:='58aa4340-8f21-4b7f-9a10-90be2da89c01';workspace uuid:=gen_random_uuid();foreign_workspace uuid:=gen_random_uuid();owner uuid:=gen_random_uuid();target uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();unverified uuid:=gen_random_uuid();member uuid:=gen_random_uuid();foreign_member uuid:=gen_random_uuid();unverified_member uuid:=gen_random_uuid();result jsonb;page jsonb;version uuid;old_version uuid;first_target_version uuid;before jsonb;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(owner,'owner-admission@example.org',clock_timestamp()),(target,'target-admission@example.org',clock_timestamp()),(outsider,'outside-admission@example.org',clock_timestamp()),(unverified,'unverified-admission@example.org',NULL);
 INSERT INTO public.user_roles VALUES(outsider,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug,created_by) VALUES(workspace,'Ownership admission fixture','ownership-admission-fixture',owner),(foreign_workspace,'Foreign ownership fixture','foreign-ownership-fixture',outsider);
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(workspace,owner),(foreign_workspace,outsider);
 INSERT INTO public.redirect_workspace_members(id,workspace_id,user_id,kind,label,role) VALUES(member,workspace,target,'user','Verified future member','viewer'),(foreign_member,foreign_workspace,outsider,'user','Foreign member','member'),(unverified_member,workspace,unverified,'user','Unverified future member','member');
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',workspace,'x-qg-redirect-session-actor',owner)::text,true);
 page:=public.redirect_workspace_ownership(owner,workspace,'owners');
 IF page->>'count'<>'1' OR(page->>'legacy')::boolean OR page#>>'{data,0,userId}' IS DISTINCT FROM owner::text OR(page#>>'{data,0,canRemove}')::boolean THEN RAISE EXCEPTION 'Provisioning registry lost exact Owner/last-Owner state';END IF;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'revoke',p_user=>owner,p_version=>(page#>>'{data,0,version}')::uuid);RAISE EXCEPTION 'Last provisioning Owner removed';EXCEPTION WHEN check_violation THEN NULL;END;
 old_version:=(page#>>'{data,0,version}')::uuid;
 page:=public.redirect_workspace_ownership(owner,workspace,'candidates',p_limit=>1);
 IF page->>'count'<>'2' OR page->>'nextCursor' IS NULL OR jsonb_array_length(page->'data')<>1 THEN RAISE EXCEPTION 'Candidate count/cursor lost';END IF;
 result:=public.redirect_workspace_ownership(owner,workspace,'candidates',p_limit=>1,p_after=>(page->>'nextCursor')::uuid);
 IF jsonb_array_length(result->'data')<>1 OR result#>>'{data,0,memberId}'=page#>>'{data,0,memberId}' THEN RAISE EXCEPTION 'Candidate cursor repeated or omitted a row';END IF;
 IF page::text LIKE '%email%' OR page::text LIKE '%token%' THEN RAISE EXCEPTION 'Owner metadata exposed account-private fields';END IF;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'admit',p_member=>foreign_member,p_expected_role=>'member');RAISE EXCEPTION 'Foreign membership admitted';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'admit',p_member=>unverified_member,p_expected_role=>'member');RAISE EXCEPTION 'Unverified account admitted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'admit',p_member=>member,p_expected_role=>'member');RAISE EXCEPTION 'Stale member role admitted';EXCEPTION WHEN unique_violation THEN NULL;END;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) INTO before FROM public.user_roles r;
 result:=public.redirect_workspace_ownership(owner,workspace,'admit',p_member=>member,p_expected_role=>'viewer');version:=(result->>'version')::uuid;
 IF result->>'userId' IS DISTINCT FROM target::text OR NOT(result->>'canRemove')::boolean OR NOT redirect_internal.workspace_owner(workspace,target) OR EXISTS(SELECT FROM public.user_roles WHERE user_id=target) THEN RAISE EXCEPTION 'Explicit Owner admission failed or escalated application role';END IF;
 IF (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM public.user_roles r) IS DISTINCT FROM before THEN RAISE EXCEPTION 'Owner admission changed application role records';END IF;
 IF public.redirect_workspace_ownership(owner,workspace,'admit',p_member=>member,p_expected_role=>'viewer')->>'version' IS DISTINCT FROM version::text THEN RAISE EXCEPTION 'Admission retry mutated an existing Owner grant';END IF;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'revoke',p_user=>target,p_version=>gen_random_uuid());RAISE EXCEPTION 'Stale Owner revision removed';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM redirect_internal.require_owner_membership_transition(workspace,member,'delete','{}');RAISE EXCEPTION 'Membership deletion implied explicit Owner revocation';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM redirect_internal.require_owner_membership_transition(workspace,member,'update','{"role":"member"}');RAISE EXCEPTION 'Membership role editor concealed Owner access';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM redirect_internal.require_owner_membership_transition(workspace,member,'update','{"active":false}');RAISE EXCEPTION 'Membership deactivation concealed Owner access';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM redirect_internal.require_owner_membership_transition(workspace,member,'update','{"label":"Renamed account"}');
 first_target_version:=version;
 PERFORM public.redirect_workspace_ownership(owner,workspace,'revoke',p_user=>target,p_version=>version);
 IF redirect_internal.workspace_owner(workspace,target) OR NOT EXISTS(SELECT FROM public.redirect_workspace_members WHERE id=member AND active AND role='viewer') THEN RAISE EXCEPTION 'Owner removal did not preserve the existing base membership';END IF;
 PERFORM redirect_internal.require_owner_membership_transition(workspace,member,'update','{"role":"member"}');
 result:=public.redirect_workspace_ownership(owner,workspace,'admit',p_member=>member,p_expected_role=>'viewer');version:=(result->>'version')::uuid;
 IF version=first_target_version THEN RAISE EXCEPTION 'Re-admission reused stale Owner revision';END IF;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'revoke',p_user=>target,p_version=>first_target_version);RAISE EXCEPTION 'Prior grant revision removed re-admitted Owner';EXCEPTION WHEN unique_violation THEN NULL;END;
 -- Global application administration is not ownership of another workspace.
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',workspace,'x-qg-redirect-session-actor',outsider)::text,true);
 BEGIN PERFORM public.redirect_workspace_ownership(outsider,workspace,'owners');RAISE EXCEPTION 'Global admin inherited future Owner access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_ownership(owner,workspace,'owners');RAISE EXCEPTION 'Contradictory session actor accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',workspace,'x-qg-redirect-session-actor',target)::text,true);
 result:=public.redirect_workspace_ownership(target,workspace,'revoke',p_user=>owner,p_version=>old_version);
 IF result->>'removed'<>'true' OR result->>'remainingOwners'<>'1' OR redirect_internal.workspace_owner(workspace,owner) THEN RAISE EXCEPTION 'Removed explicit Owner retained authority';END IF;
 BEGIN PERFORM public.redirect_workspace_ownership(target,workspace,'revoke',p_user=>target,p_version=>version);RAISE EXCEPTION 'Last Owner removed after handoff';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_context(target,p_workspace=>workspace);RAISE EXCEPTION 'Registry admission activated business context';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO public.redirects(workspace_id,type,slug,target) VALUES(workspace,'SHORT','owner-registry-fence-fixture','https://example.org/fenced');RAISE EXCEPTION 'Registry admission removed tenant write fences';EXCEPTION WHEN check_violation THEN NULL;END;
 IF (SELECT status FROM public.redirect_workspaces WHERE id=workspace)<>'provisioning' THEN RAISE EXCEPTION 'Registry operation activated tenant';END IF;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',legacy,'x-qg-redirect-session-actor',outsider)::text,true);
 IF NOT(public.redirect_workspace_ownership(outsider,legacy,'owners')->>'legacy')::boolean THEN RAISE EXCEPTION 'Legacy ownership model hidden';END IF;
 BEGIN PERFORM public.redirect_workspace_ownership(outsider,legacy,'admit',p_member=>member,p_expected_role=>'viewer');RAISE EXCEPTION 'Ownership endpoint expanded application admin access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_function_privilege('authenticated','public.redirect_workspace_ownership(uuid,uuid,text,uuid,uuid,uuid,text,integer,uuid)','EXECUTE') OR has_function_privilege('anon','redirect_internal.workspace_owner_json(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Private ownership authority exposed';END IF;
END $$;
ROLLBACK;
